// Extract the JSON report from the agent output
const output = $input.all()[0].json.output;

// Find the CLEARPATH_REPORT: marker and extract JSON after it
const marker = 'CLEARPATH_REPORT:';
const markerIndex = output.indexOf(marker);

if (markerIndex === -1) {
  throw new Error('CLEARPATH_REPORT: marker not found in output');
}

let jsonString = output.substring(markerIndex + marker.length).trim();

// Strip markdown code fences if present
if (jsonString.startsWith('```')) {
  jsonString = jsonString.replace(/^```(?:json)?\s*/, '').replace(/```\s*$/, '').trim();
}

// Strip anything after the JSON object closes (trailing conversational text)
const lastBrace = jsonString.lastIndexOf('}');
if (lastBrace !== -1) {
  jsonString = jsonString.substring(0, lastBrace + 1);
}

try {
  const report = JSON.parse(jsonString);
  return [{ json: { output: JSON.stringify(report) } }];
} catch (e) {
  throw new Error('Failed to parse JSON report: ' + e.message);
}

